// ============================================================

function generateVCard(info) {
  const a = info.address || {};
  const lines = [
    "BEGIN:VCARD",
    "VERSION:3.0",
    `N:${info.last_name};${info.first_name};;;`,
    `FN:${info.first_name} ${info.last_name}`,
    `EMAIL;TYPE=INTERNET:${info.email || ""}`,
    `TEL;TYPE=CELL:${info.phone || ""}`,
    `ADR;TYPE=HOME:;;${a.street||""};${a.city||""};${a.state||""};${a.zip||""};${a.country|""}`,
  ];

  if (info.account_email && info.account_email !== info.email) {
    lines.push(`EMAIL;TYPE=INTERNET,WORK:${info.account_email}`);
  }

  const noteParts = [];
  if (info.account_id) noteParts.push(`Account ID: ${info.account_id}`);
  for (const o of info.orders || []) {
    noteParts.push(`Order: ${o.order_id} | ${o.date||""} | ${o.total||""} | ${o.status||""}`);
  }
  for (const pm of info.payment_methods || []) {
    noteParts.push(`Payment: ${pm.id} (${pm.brand||""} ****${pm.last_four||""} exp ${pm.exp_month|""}/${pm.exp_year|""})`);
  }
  if (info.notes) noteParts.push(info.notes);
  if (noteParts.length) lines.push(`NOTE:${noteParts.join(" | ")}`);

  lines.push("END:VCARD");
  return lines.join("\n");
}

function saveFiles(info) {
  const dir = __dirname;
  const base = `${info.first_name}_${info.last_name}`.toLowerCase();
  const ts = new Date().toISOString();

  // vCard
  const vcfPath = path.join(dir, `${base}.vcf`);
  fs.writeFileSync(vcfPath, generateVCard(info));
  console.log(`✅ vCard saved:  ${vcfPath}`);

  // JSON
  const jsonPath = path.join(dir, `${base}_account.json`);
  const exported = { exported_at: ts, ...info };
  fs.writeFileSync(jsonPath, JSON.stringify(exported, null, 2));
  console.log(`✅ JSON saved:   ${jsonPath}`);

  console.log(`\n📱 To add the contact to your device:`);
  console.log(`   • iOS/Android: Open or share the .vcf file`);
  console.log(`   • macOS:       Double-click the .vcf → Contacts`);
  console.log(`   • Windows:     Import .vcf into People/Outlook`);
  console.log(`   • Google:      contacts.google.com → Import → select .vcf`);
}

console.log("=".repeat(50));
