function generateVCard(info) {
  const a = info.address || {};
  const lines = [
    "BEGIN:VCARD",
    "VERSION:3.0",
    `N:${info.last_name};${info.first_name};;;`,
    `FN:${info.first_name} ${info.last_name}`,
    `EMAIL;TYPE=INTERNET:${info.email || ""}`,
    `TEL;TYPE=CELL:${info.phone || ""}`,
    `ADR;TYPE=HOME:;;${a.street||""};${a.city||""};${a.state||""};${a.zip||""};${a.country||""}`,
  ];

  // Account email as a secondary/work email
  if (info.account_email && info.account_email !== info.email) {
    lines.push(`EMAIL;TYPE=INTERNET,WORK:${info.account_email}`);
  }

  // ── X- Custom Fields (structured, machine-readable) ──
  // These follow the vCard convention for vendor/app-specific data.
  // Format: X-<APPNAME>-<FIELDNAME>:value
  if (info.account_id) {
    lines.push(`X-ACCOUNT-ID:${info.account_id}`);
  }

  // One X- field per order, semicolon-delimited subfields
  for (const o of info.orders || []) {
    const parts = [
      o.order_id || "",
      o.date || "",
      o.total || "",
      o.status || "",
      (o.items || []).join(","),
    ];
    lines.push(`X-ORDER:${parts.join(";")}`);
  }

  // One X- field per payment method, semicolon-delimited subfields
  for (const pm of info.payment_methods || []) {
    const parts = [
      pm.id || "",
      pm.type || "",
      pm.brand || "",
      pm.last_four ? `****${pm.last_four}` : "",
      pm.exp_month && pm.exp_year ? `${pm.exp_month}/${pm.exp_year}` : "",
      pm.billing_name || "",
    ];
    lines.push(`X-PAYMENT:${parts.join(";")}`);
  }

  // ── NOTE field (human-readable fallback) ──
  // Apps that ignore X- fields will still show this summary.
  const noteParts = [];
  if (info.account_id) noteParts.push(`Account: ${info.account_id}`);
  for (const o of info.orders || []) {
    const detail = [o.order_id, o.date, o.total, o.status].filter(Boolean).join(" / ");
    noteParts.push(`Order: ${detail}`);
  }
  for (const pm of info.payment_methods || []) {
    const detail = [pm.id, pm.brand, pm.last_four ? `****${pm.last_four}` : "", 
      pm.exp_month && pm.exp_year ? `exp ${pm.exp_month}/${pm.exp_year}` : ""].filter(Boolean).join(" ");
    noteParts.push(`Payment: ${detail}`);
  }
  if (info.notes) noteParts.push(info.notes);
  if (noteParts.length) lines.push(`NOTE:${noteParts.join("\\n")}`);

  lines.push("END:VCARD");
  return lines.join("\n");
}
